{"path": "/tmp/sv-4272cd9b79a4478b83146b60a9efb3f8/Components/Pages/Apply.razor", "file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_4272cd9b79a4478b83146b60a9efb3f8.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <!-- Step Indicator Bar -->
    <div class="step-indicator">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < currentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@stepNames[stepIndex]</div>
            </div>
            @if (i < stepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (currentStep == 0)
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="fullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <textarea id="address" @bind="address" placeholder="Enter your address"></textarea>
            </div>
            <div class="form-actions">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                    @(isValidating ? "Validating..." : "Next")
                </button>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (currentStep == 1)
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (workEntries.Count > 1)
                        {
                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="workEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="workEntries[index].EndDate" disabled="@workEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group form-check">
                        <input type="checkbox" id="current-@index" @bind="workEntries[index].IsCurrent" />
                        <label for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea @bind="workEntries[index].Description" placeholder="Describe your responsibilities and achievements"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-actions">
                <button class="btn btn-outline" @onclick="() => currentStep = 0">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (currentStep == 2)
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < references.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (references.Count > 2)
                        {
                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="references[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="references[index].Relationship" placeholder="e.g., Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="references[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="references[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (references.Count < 3)
            {
                <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-actions">
                <button class="btn btn-outline" @onclick="() => currentStep = 1">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (currentStep == 3)
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter *</label>
                <textarea id="coverLetter" class="cover-letter-textarea" @bind="coverLetter" @bind:event="oninput" placeholder="Write your cover letter here..." maxlength="2000"></textarea>
                <div class="character-count @(coverLetter.Length > 1800 ? "warning" : "")">
                    @coverLetter.Length / 2000 characters
                </div>
            </div>
            <div class="form-actions">
                <button class="btn btn-outline" @onclick="() => currentStep = 2">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (currentStep == 4)
    {
        <div class="step-content">
            @if (isSubmitted)
            {
                <div class="submission-confirmation">
                    <div class="success-icon">✓</div>
                    <h2>Application Submitted Successfully!</h2>
                    <p>Your application ID is: <strong>#@applicationId</strong></p>
                    <p>Thank you for applying. We will review your application and get back to you soon.</p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <!-- Personal Info Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-link" @onclick="() => currentStep = 0">Edit</button>
                    </div>
                    <div class="review-content">
                        <p><strong>Name:</strong> @fullName</p>
                        <p><strong>Email:</strong> @email</p>
                        <p><strong>Phone:</strong> @phone</p>
                        <p><strong>Address:</strong> @address</p>
                    </div>
                </div>

                <!-- Work History Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-link" @onclick="() => currentStep = 1">Edit</button>
                    </div>
                    <div class="review-content">
                        @foreach (var entry in workEntries)
                        {
                            <div class="review-work-entry">
                                <p><strong>@entry.Title</strong> at @entry.Company</p>
                                <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                                <p>@entry.Description</p>
                            </div>
                        }
                    </div>
                </div>

                <!-- References Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-link" @onclick="() => currentStep = 2">Edit</button>
                    </div>
                    <div class="review-content">
                        @foreach (var reference in references)
                        {
                            <div class="review-reference">
                                <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                                <p>@reference.Email | @reference.Phone</p>
                            </div>
                        }
                    </div>
                </div>

                <!-- Cover Letter Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-link" @onclick="() => currentStep = 3">Edit</button>
                    </div>
                    <div class="review-content">
                        <p class="cover-letter-preview">@coverLetter</p>
                    </div>
                </div>

                <div class="form-actions">
                    <button class="btn btn-outline" @onclick="() => currentStep = 3">Back</button>
                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @(isSubmitting ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            }
        </div>
    }
</div>

@code {
    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int currentStep = 0;
    private string errorMessage = string.Empty;
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;

    // Step 1: Personal Info
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string coverLetter = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == currentStep) return "active";
        if (stepIndex < currentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < currentStep)
        {
            currentStep = stepIndex;
            errorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
            if (!isValidEmail)
            {
                errorMessage = "The email address is not valid. Please enter a valid email.";
                return;
            }
            currentStep = 1;
        }
        finally
        {
            isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        errorMessage = string.Empty;

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
            {
                errorMessage = "Please fill in all required fields for each work entry.";
                return;
            }
            if (!entry.IsCurrent && entry.EndDate == null)
            {
                errorMessage = "Please provide an end date or mark the position as current.";
                return;
            }
        }

        currentStep = 2;
    }

    private void NextFromReferences()
    {
        errorMessage = string.Empty;

        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                errorMessage = "Please fill in all required fields for each reference.";
                return;
            }
        }

        currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            errorMessage = "Please write a cover letter.";
            return;
        }

        currentStep = 4;
    }

    private void AddWorkEntry()
    {
        workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
        {
            workEntries.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
        {
            references.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
        {
            references.RemoveAt(index);
        }
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        errorMessage = string.Empty;

        try
        {
            var personalInfo = new PersonalInfo(fullName, email, phone, address);
            var workHistory = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personalInfo, workHistory, refs, coverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"An error occurred while submitting your application: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
"}

